#!/usr/bin/env bash
# setup_deps.sh — generated by gen_setup_deps.py
# Task: git-multibranch
# Base image: ubuntu:24.04
#
# Sets up the task workspace at $WORKDIR (default: /app).
# TB_ROOT points at the terminal-bench-2 checkout.
# EXTRAS_ROOT: redirect out-of-/app copy destinations (e.g. /protected →
#   $EXTRAS_ROOT/protected). Set by runner to ~/bench/extras/<task>.
#
# Usage:
#   [TB_ROOT=~/z2/terminal-bench-2] [WORKDIR=/app] [EXTRAS_ROOT=] bash setup_deps.sh

set -euo pipefail

TB_ROOT="${TB_ROOT:-$HOME/z2/terminal-bench-2}"
TASK_ENV="$TB_ROOT/git-multibranch/environment"
WORKDIR="${WORKDIR:-/app}"
EXTRAS_ROOT="${EXTRAS_ROOT:-}"

# ── source common base tooling ──────────────────────────────────────────────
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BASE_SCRIPT="$(dirname "$(dirname "$SCRIPT_DIR")")/setup_base.sh"
if [[ -f "$BASE_SCRIPT" ]]; then
  # shellcheck source=/dev/null
  source "$BASE_SCRIPT"
fi

mkdir -p "$WORKDIR"

# (no ENV directives)
# ── system packages ─────────────────────────────────────────────────────────
# Set SKIP_APT=1 when packages are pre-installed on the host (runner sets this)
if [[ -z "${SKIP_APT:-}" ]]; then
  sudo apt-get update -qq
  sudo apt-get install -y --no-install-recommends \
    ca-certificates curl git net-tools nginx openssh-server openssl python3 python3-pip
  sudo rm -rf /var/lib/apt/lists/*
fi
# ── copy task assets ───────────────────────────────────────────────────────
mkdir -p "$(dirname "${EXTRAS_ROOT:-}/etc/nginx/sites-available/default")"
cp -r "$TASK_ENV/default.conf" "${EXTRAS_ROOT:-}/etc/nginx/sites-available/default"
# (no pip packages)
cd "$WORKDIR"
# ── unclassified RUN directives ────────────────────────────────────────────
# RAW: mkdir -p /etc/ssl/certs && mkdir -p /etc/ssl/private && openssl req -x509 -nodes -days 365 -subj "/CN=localhost" -newkey rsa:2048 -keyout /etc/ssl/private/nginx-selfsigned.key -out /etc/ssl/certs/nginx-selfsigned.crt
mkdir -p /etc/ssl/certs && mkdir -p /etc/ssl/private && openssl req -x509 -nodes -days 365 -subj "/CN=localhost" -newkey rsa:2048 -keyout /etc/ssl/private/nginx-selfsigned.key -out /etc/ssl/certs/nginx-selfsigned.crt
# RAW: mkdir -p /var/www/html /var/www/dev
mkdir -p /var/www/html /var/www/dev
echo "[setup_deps] git-multibranch ready — workspace: $WORKDIR"
